details.command:
kubectl exec deploy/app -- sh -c 'curl -sS -o /dev/null -w "%{http_code}
" http://10.244.0.5:80/ ; curl -sS -o /dev/null -w "%{http_code}
" http://app.default.svc.cluster.local/ ; curl -sS -o /dev/null -w "%{http_code}
" http://10.96.183.63/ ; curl -sS -o /dev/null -w "%{http_code}
" http://10.96.183.63:8080/' 2>&1 | tail -30; echo ---; kubectl get deploy,rs -l app=app

kubectl exec deploy/app -- sh -c 'curl -sS -o /dev/null -w "80:%{http_code}
" http://10.244.0.5:80/ ; echo "--- via service ---"; curl -sS -o /dev/null -w "svc:%{http_code}
" http://app.default.svc.cluster.local/; echo "--- via ClusterIP ---"; curl -sS -o /dev/null -w "cp:%{http_code}
" http://10.96.183.63/ ; echo "--- targetPort explicitly ---"; curl -sS -o /dev/null -w "tp8080:%{http_code}
" http://10.96.183.63:8080/' 2>&1 | tail -30
